:root {
  color-scheme: light;
  --ink: #172d3a;
  --muted: #647983;
  --line: #dce8e8;
  --surface: #fff;
  --canvas: #f2f7f7;
  --teal: #087e83;
  --teal-dark: #06666d;
  --teal-soft: #e5f5f2;
  --amber: #986316;
  --amber-soft: #fff3d9;
  --green: #27764e;
  --green-soft: #e7f5eb;
  --danger: #ad3540;
  --shadow: 0 12px 32px rgba(27, 64, 72, .07);
  font-family: Inter, "Apple SD Gothic Neo", "Noto Sans KR", "Malgun Gothic", sans-serif;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
}
* { box-sizing: border-box; }
body { margin: 0; min-width: 320px; background: var(--canvas); color: var(--ink); }
button, input { font: inherit; }
button { color: inherit; }
.board { width: min(100% - 48px, 1040px); margin: 0 auto; padding: 44px 0 28px; }
.page-header { display: flex; align-items: center; gap: 18px; margin-bottom: 27px; }
.brand-mark { display: grid; place-items: center; width: 54px; height: 54px; border-radius: 17px; background: var(--teal); color: #fff; font-size: 25px; font-weight: 800; box-shadow: 0 8px 20px rgba(8,126,131,.2); }
.eyebrow { margin: 0 0 5px; color: var(--teal); font-size: 11px; font-weight: 800; letter-spacing: .12em; text-transform: uppercase; }
h1, h2, h3, p { margin-top: 0; }
h1 { margin-bottom: 4px; font-size: clamp(25px, 4vw, 32px); line-height: 1.15; letter-spacing: -.04em; }
.intro { margin: 0; color: var(--muted); font-size: 14px; }
.summary { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 12px; margin-bottom: 20px; }
.summary-card { position: relative; min-height: 106px; padding: 17px 19px; border: 1px solid var(--line); border-radius: 15px; background: var(--surface); box-shadow: 0 4px 16px rgba(27,64,72,.035); }
.summary-label { display: block; margin-bottom: 10px; color: var(--muted); font-size: 12px; font-weight: 650; }
.summary-card strong { font-size: 29px; line-height: 1; letter-spacing: -.04em; }
.summary-unit { margin-left: 6px; color: var(--muted); font-size: 12px; }
.summary-total { border-color: #c6e4e1; background: linear-gradient(140deg, #f3fcfa, #fff 70%); }
.summary-total strong { color: var(--teal-dark); }
.panel { padding: 23px 25px; border: 1px solid var(--line); border-radius: 18px; background: var(--surface); box-shadow: var(--shadow); }
.composer { margin-bottom: 18px; }
.section-heading { display: flex; align-items: center; justify-content: space-between; gap: 16px; }
.section-heading h2 { margin: 0; font-size: 19px; letter-spacing: -.025em; }
.heading-icon { display: grid; place-items: center; width: 34px; height: 34px; border-radius: 11px; background: var(--teal-soft); color: var(--teal); font-size: 21px; }
.form-fields { display: grid; grid-template-columns: minmax(200px, 1.6fr) minmax(145px, 1fr) minmax(112px, .65fr) auto; align-items: end; gap: 12px; margin-top: 19px; }
.field { min-width: 0; }
.field label { display: block; margin: 0 0 7px; color: #425963; font-size: 12px; font-weight: 750; }
.field label span { color: var(--muted); font-weight: 500; }
.field input, .search-box input { width: 100%; min-width: 0; border: 1px solid #cbdada; border-radius: 10px; outline: none; background: #fbfdfd; color: var(--ink); transition: border-color .16s, box-shadow .16s, background .16s; }
.field input { height: 43px; padding: 0 12px; }
input::placeholder { color: #99a9ad; }
.field input:focus, .search-box input:focus { border-color: var(--teal); background: #fff; box-shadow: 0 0 0 3px rgba(8,126,131,.12); }
.primary-button, .filter-button, .task-action { border: 0; cursor: pointer; transition: background .16s, color .16s, transform .16s; }
.primary-button { display: inline-flex; align-items: center; justify-content: center; gap: 7px; min-height: 43px; padding: 0 17px; border-radius: 10px; background: var(--teal); color: #fff; font-size: 13px; font-weight: 750; white-space: nowrap; }
.primary-button:hover { background: var(--teal-dark); }
button:active { transform: translateY(1px); }
