.list-toolbar { display: flex; align-items: center; justify-content: space-between; gap: 14px; margin-top: 21px; padding-bottom: 16px; border-bottom: 1px solid #edf2f2; }
.filters { display: flex; gap: 6px; }
.filter-button { min-height: 32px; padding: 0 12px; border-radius: 8px; background: transparent; color: var(--muted); font-size: 12px; font-weight: 700; }
.filter-button:hover { background: #f0f6f6; color: var(--ink); }
.filter-button.is-selected { background: var(--teal-soft); color: var(--teal-dark); }
.list-hint { color: #819196; font-size: 11px; text-align: right; }
.status-message { min-height: 0; margin: 0; color: var(--teal-dark); font-size: 12px; }
.status-message:not(:empty) { padding-top: 12px; }
.empty-state { padding: 35px 16px 30px; color: var(--muted); text-align: center; }
.empty-icon { display: grid; place-items: center; width: 43px; height: 43px; margin: 0 auto 12px; border-radius: 15px; background: #eff7f6; color: var(--teal); font-size: 22px; }
.empty-state h3 { margin: 0 0 7px; color: var(--ink); font-size: 15px; }
.empty-state p { margin: 0; font-size: 12px; line-height: 1.6; }
.empty-state[hidden] { display: none; }
.task-list { display: grid; gap: 10px; margin: 0; padding: 15px 0 0; list-style: none; }
.task { display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: center; gap: 15px; min-width: 0; padding: 15px 16px; border: 1px solid var(--line); border-radius: 13px; background: #fff; }
.task-main { min-width: 0; }
.task-title-row { display: flex; align-items: flex-start; gap: 9px; min-width: 0; }
.task-title { min-width: 0; margin: 0; overflow-wrap: anywhere; font-size: 14px; font-weight: 750; line-height: 1.55; }
.task-status { flex: none; margin-top: 1px; padding: 4px 8px; border-radius: 999px; background: var(--amber-soft); color: var(--amber); font-size: 10px; font-weight: 750; }
.task.is-completed .task-status { background: var(--green-soft); color: var(--green); }
.task.is-completed .task-title { color: #718087; text-decoration: line-through; text-decoration-color: #9baaad; }
.task-meta { display: flex; flex-wrap: wrap; gap: 7px 12px; margin-top: 7px; color: var(--muted); font-size: 11px; }
.task-subject { color: var(--teal-dark); font-weight: 700; }
.task-actions { display: flex; flex: none; gap: 7px; }
.task-action { min-height: 33px; padding: 0 10px; border: 1px solid var(--line); border-radius: 8px; background: #fff; color: #526970; font-size: 11px; font-weight: 700; white-space: nowrap; }
.task-action:hover { background: #f4f8f8; }
.task-action[data-action="delete"] { color: var(--danger); }
.task-action[data-action="delete"]:hover { background: #fff2f2; }
.page-footer { padding: 19px 4px 0; color: #87969a; font-size: 11px; text-align: center; }
@media (max-width: 720px) {
  .board { width: min(100% - 32px, 560px); padding-top: 27px; }
  .summary { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 9px; }
  .summary-card { min-height: 88px; padding: 14px 15px; }
  .summary-label { margin-bottom: 8px; }
  .summary-card strong { font-size: 25px; }
  .panel { padding: 19px 17px; border-radius: 15px; }
  .form-fields { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 13px 10px; }
  .field-title { grid-column: 1 / -1; }
  .primary-button { align-self: end; }
  .list-heading { align-items: stretch; flex-direction: column; gap: 13px; }
  .search-box { width: 100%; }
  .list-toolbar { align-items: flex-start; flex-direction: column; gap: 10px; margin-top: 16px; }
  .list-hint { text-align: left; }
}
@media (max-width: 430px) {
  .board { width: min(100% - 24px, 400px); padding-top: 22px; }
  .page-header { gap: 13px; margin-bottom: 20px; }
  .brand-mark { width: 46px; height: 46px; border-radius: 14px; }
  .intro { max-width: 260px; font-size: 12px; }
  .task { grid-template-columns: minmax(0, 1fr); gap: 12px; padding: 13px; }
  .task-actions { justify-content: flex-end; }
  .task-title-row { flex-wrap: wrap; }
  .empty-state { padding: 29px 8px 25px; }
}
